/**
 * Common alternate names + abbreviations that buyers might type into the
 * country search box. Used by `searchableNames(code)` so the picker matches
 * "USA" → US, "UK" → GB, "Holland" → NL, etc.
 *
 * Keep keys lowercase. Whatever Intl.DisplayNames returns for the active
 * locale is already searchable on top of these aliases.
 */
const COUNTRY_ALIASES: Record<string, string[]> = {
  US: ["usa", "america", "united states of america"],
  GB: ["uk", "britain", "great britain", "england"],
  NL: ["holland"],
  KR: ["korea", "south korea"],
  KP: ["north korea", "dprk"],
  RU: ["russian federation"],
  CD: ["congo-kinshasa", "drc"],
  CG: ["congo-brazzaville"],
  CZ: ["czech republic"],
  CI: ["ivory coast"],
  MM: ["burma"],
  TL: ["east timor"],
  SZ: ["swaziland"],
  CV: ["cabo verde"],
  TR: ["türkiye", "turkiye"],
  MK: ["macedonia"],
  PS: ["palestinian territory"],
  HK: ["hong kong sar"],
  MO: ["macau", "macao sar"],
  TW: ["chinese taipei", "republic of china"],
  AE: ["uae", "emirates"],
  SA: ["ksa"],
  VA: ["holy see", "vatican"],
};

/**
 * Returns lowercase haystack tokens for matching a country in search:
 * the localized name + the ISO code + the English name + any known aliases.
 */
export function searchableNames(code: string, localizedName: string): string[] {
  const upper = code.toUpperCase();
  const enName = COUNTRIES_BY_CODE[upper]?.nameEn ?? "";
  return [
    localizedName.toLowerCase(),
    upper.toLowerCase(),
    enName.toLowerCase(),
    ...(COUNTRY_ALIASES[upper] ?? []),
  ].filter((s) => s.length > 0);
}

/**
 * Country flag emoji from an ISO 3166-1 alpha-2 code.
 * Each letter is mapped to the corresponding regional indicator codepoint.
 * Example: "CA" → 🇨🇦.
 *
 * Returns the input code unchanged if it isn't a valid 2-letter ISO code,
 * so callers can render it as a string fallback.
 *
 * Note: Windows native fonts do not include colored flag glyphs — these
 * emoji render as letter pairs there. For UI surfaces that need flags to
 * render cross-platform, use `countryFlagImageUrl(code)` which points to
 * flagcdn.com PNGs.
 */
export function countryFlagEmoji(code: string): string {
  if (typeof code !== "string" || code.length !== 2) return code;
  const upper = code.toUpperCase();
  if (!/^[A-Z]{2}$/.test(upper)) return code;
  const base = 0x1f1e6 - 65;
  return String.fromCodePoint(upper.charCodeAt(0) + base, upper.charCodeAt(1) + base);
}

/**
 * URL to a hosted PNG flag for the given ISO 3166-1 alpha-2 code.
 * Uses flagcdn.com (free, no auth, public CDN). Pick a height in px to
 * size the image — provide `1x` widths like 16, 20, 24, 40, 80, 160, 240.
 *
 * Returns null for invalid codes so callers can fall back gracefully.
 *
 * Example:
 *   <img src={countryFlagImageUrl("CA", 20)} width={27} height={20} />
 */
export function countryFlagImageUrl(
  code: string,
  height: 16 | 20 | 24 | 40 | 80 | 160 | 240 = 20,
): string | null {
  if (typeof code !== "string" || code.length !== 2) return null;
  const upper = code.toUpperCase();
  if (!/^[A-Z]{2}$/.test(upper)) return null;
  return `https://flagcdn.com/h${height}/${upper.toLowerCase()}.png`;
}

const COUNTRIES_BY_CODE: Record<string, Country> = Object.fromEntries(
  COUNTRIES.map((c) => [c.code, c]),
);

export function getCountry(code: string): Country | null {
  return COUNTRIES_BY_CODE[code.toUpperCase()] ?? null;
}

export function isValidCountryCode(code: string): boolean {
  return code.toUpperCase() in COUNTRIES_BY_CODE;
}

export function localizedCountryName(code: string, locale = "en-US"): string {
  try {
    const display = new Intl.DisplayNames([locale], { type: "region" });
    return display.of(code.toUpperCase()) ?? code;
  } catch {
    // error-surfaced: an unsupported locale falls back to the English country name
    return getCountry(code)?.nameEn ?? code;
  }
}

