/**
 * Resolves "what country is this buyer probably in?" from the UI locale.
 * Used for the market "ships to my country" filter chip.
 *
 * Note: this is a best-effort hint, not authoritative. Future improvement:
 * read from a buyer profile setting, or geo-IP at the edge.
 */
export function inferBuyerCountry(locale: string): string {
  const lower = locale.toLowerCase();
  if (lower.startsWith("fr")) return "CA";
  if (lower.startsWith("en")) return "CA";
  if (lower.startsWith("es")) return "MX";
  if (lower.startsWith("de")) return "DE";
  if (lower.startsWith("it")) return "IT";
  if (lower.startsWith("pt")) return "PT";
  if (lower.startsWith("ja")) return "JP";
  if (lower.startsWith("ko")) return "KR";
  if (lower.startsWith("zh")) return "CN";
  return "CA";
}

/**
 * Determines the effective shipping countries for a listing.
 * Per-listing profile wins; falls back to seller's default profile.
 * Returns empty array if neither is set (i.e. local pickup only).
 */
export function resolveShippingCountries(
  listingProfile: { shipsToCountries: string[] } | null,
  sellerDefaultProfile: { shipsToCountries: string[] } | null,
): string[] {
  if (listingProfile && listingProfile.shipsToCountries.length > 0) {
    return listingProfile.shipsToCountries;
  }
  return sellerDefaultProfile?.shipsToCountries ?? [];
}
