import { z } from "zod";
import { ENTITLEMENT_FEATURES, SELLER_SUBSCRIPTION_TIERS } from "../enums";

/**
 * The authenticated principal behind an API key, plus the plan that governs what the key may do.
 * This is the endpoint an SDK calls to verify a key and to decide, client-side, whether a write
 * would 402 before attempting it.
 */
export const V1UserSchema = z.object({
  id: z.string(),
  email: z.email(),
  name: z.string(),
});
export type V1User = z.infer<typeof V1UserSchema>;

/**
 * Plan limits as they cross the wire.
 *
 * TIER_LIMITS stores unlimited as `Number.POSITIVE_INFINITY`, which JSON cannot represent — so
 * every limit that can be unlimited is `integer | null` here, with **null meaning unlimited**.
 * Limits that are always finite (apiRequestsPerMonth: 0 / 5000 / 50000) stay plain integers.
 */
export const V1PlanLimitsSchema = z.object({
  maxActiveListings: z
    .int()
    .nonnegative()
    .nullable()
    .describe(
      "Max simultaneously-active listings; null means unlimited. Enforced at the publish " +
        "transition, not at creation.",
    ),
  aiCopilotRunsPerMonth: z
    .int()
    .nonnegative()
    .nullable()
    .describe("AI copilot runs per month; null means unlimited."),
  apiRequestsPerMonth: z
    .int()
    .nonnegative()
    .describe(
      "ADVISORY, not currently enforced: the published monthly request allowance for the tier " +
        "(0 on free, and finite on every tier). No monthly counter is metered against it today. " +
        "The limit that IS enforced is a per-key burst budget of 1000 requests, whose window " +
        "clears only after 60 consecutive seconds of idle time; exceeding it answers 429.",
    ),
});
export type V1PlanLimits = z.infer<typeof V1PlanLimitsSchema>;

export const V1PlanSchema = z.object({
  tier: z
    .enum(SELLER_SUBSCRIPTION_TIERS)
    .describe(
      'Effective tier. A seller with no subscription — or one that lapsed — resolves to "free".',
    ),
  entitlements: z
    .array(z.enum(ENTITLEMENT_FEATURES))
    .describe('Features the effective tier unlocks. Programmatic writes require "api_write".'),
  limits: V1PlanLimitsSchema,
});
export type V1Plan = z.infer<typeof V1PlanSchema>;

export const V1MeResponseSchema = z.object({
  user: V1UserSchema,
  plan: V1PlanSchema,
});
export type V1MeResponse = z.infer<typeof V1MeResponseSchema>;
