import { z } from "zod";
import type { JsonValue } from "../contracts";

/**
 * Shared building blocks for the public v1 API contract.
 *
 * These schemas describe the WIRE shape of `/v1/*` — what the HTTP layer actually accepts and
 * returns — not the internal domain types. They deliberately mirror `../contracts.ts`, which is
 * the semantic source of truth; when a domain type changes, the matching schema here changes in
 * the same commit (the round-trip tests in `*.test.ts` fail loudly when they drift).
 *
 * Money is integer minor units everywhere, matching the rest of the codebase (see MoneyBreakdown
 * in ../contracts.ts). Every amount is `.int()` so a fractional value is rejected at the edge
 * rather than silently rounded downstream.
 */

/** Arbitrary JSON, as stored in the `*Json` columns. Recursive — emitted as a single named
 *  component so the generated OpenAPI document carries one definition and many `$ref`s. */
export const V1JsonValueSchema: z.ZodType<JsonValue> = z.lazy(() =>
  z.union([
    z.string(),
    z.number(),
    z.boolean(),
    z.null(),
    z.array(V1JsonValueSchema),
    z.record(z.string(), V1JsonValueSchema),
  ]),
);

/** ISO-8601 timestamp. Named so the (long) format pattern appears once in the OpenAPI document. */
export const V1IsoDateTimeSchema = z.iso.datetime();
export type V1IsoDateTime = z.infer<typeof V1IsoDateTimeSchema>;

export const V1GeoLocationSchema = z.object({
  latitude: z.number().min(-90).max(90).optional(),
  longitude: z.number().min(-180).max(180).optional(),
  city: z.string().optional(),
  region: z.string().optional(),
  country: z.string(),
  postalCode: z.string().optional(),
  addressLine1: z.string().optional(),
  addressLine2: z.string().optional(),
});
export type V1GeoLocation = z.infer<typeof V1GeoLocationSchema>;

/** All amounts are integer minor units of `currency`. */
export const V1MoneyBreakdownSchema = z.object({
  itemSubtotal: z.int(),
  shippingAmount: z.int(),
  taxAmount: z.int(),
  /** Always 0 on Marka — sellers are merchant of record and the marketplace fee is 0%. */
  applicationFeeAmount: z.int(),
  currency: z.string(),
});
export type V1MoneyBreakdown = z.infer<typeof V1MoneyBreakdownSchema>;

/**
 * A single amount in integer minor units — the shape every money field on this API shares, in one
 * place so a new amount cannot be declared as a float or accidentally allowed to go negative.
 *
 * Deliberately NOT used by V1MoneyBreakdownSchema above: a breakdown line is signed (a credit is a
 * legitimate negative), while a standalone amount — a price, a shipping charge, an offer floor —
 * never is.
 *
 * The description is a required argument rather than a default, because what the amount MEANS is
 * the part a client cannot infer, and every call site says something different.
 */
export function v1MinorUnits(description: string): z.ZodNumber {
  return z.int().nonnegative().describe(description);
}

/**
 * The nullable spelling of {@link v1MinorUnits}, for an amount that may be absent.
 *
 * Separate rather than an option because the `.describe()` has to land on the OUTER schema: zod
 * renders `int().describe(…).nullable()` with the description buried inside one branch of the
 * emitted `anyOf`, where an OpenAPI renderer showing property descriptions will not find it.
 */
export function v1NullableMinorUnits(description: string): z.ZodNullable<z.ZodNumber> {
  return z.int().nonnegative().nullable().describe(description);
}

export const V1PackageDimensionsMmSchema = z.object({
  lengthMm: z.int().nonnegative(),
  widthMm: z.int().nonnegative(),
  heightMm: z.int().nonnegative(),
});
export type V1PackageDimensionsMm = z.infer<typeof V1PackageDimensionsMmSchema>;

/** Mirrors the clamps in apps/web/app/api/listings/route.ts. */
export const V1_DEFAULT_PAGE_SIZE = 50;
export const V1_MAX_PAGE_SIZE = 100;

/**
 * Pagination query params. Coerced from strings because they arrive as query-string text; the
 * OpenAPI document renders them as integers, which is the logical type a client supplies.
 * Omitted values fall back to the server defaults above rather than carrying a zod `.default()`,
 * so the request and response views of this schema stay identical.
 */
export const V1PaginationQuerySchema = z.object({
  limit: z.coerce
    .number()
    .int()
    .min(1)
    .max(V1_MAX_PAGE_SIZE)
    .optional()
    .describe(`Page size, 1-${V1_MAX_PAGE_SIZE}. Defaults to ${V1_DEFAULT_PAGE_SIZE}.`),
  offset: z.coerce
    .number()
    .int()
    .min(0)
    .optional()
    .describe("Number of records to skip. Defaults to 0."),
});
export type V1PaginationQuery = z.infer<typeof V1PaginationQuerySchema>;

/** The pagination envelope every list endpoint echoes back. */
export const V1PaginationFields = {
  limit: z.int().min(1).max(V1_MAX_PAGE_SIZE),
  offset: z.int().min(0),
  hasMore: z.boolean(),
} as const;
