export type V1HttpMethod = "get" | "post" | "patch";

/**
 * Where the `/v1` paths below are actually mounted.
 *
 * The route table's paths are `/v1/…` because that is the API's own namespace, but the handlers
 * are Next App Router files under `apps/web/app/api/v1/**`, so the URL a client dials is
 * `/api/v1/…`. This constant is the ONE place that offset lives: the OpenAPI document composes it
 * into `servers[0].url` and the SDK composes it onto its base URL, so neither can drift into
 * publishing a URL that 404s.
 */
export const V1_PATH_PREFIX = "/api";

/**
 * How a route is authenticated. `apiKey` = a credential is required and a missing or revoked one
 * is a 401 — the API key is the documented credential and the only one an SDK ever sends, though
 * the handlers also honour a signed-in browser cookie (see the note on `V1_ROUTES`).
 *
 * ONE member, on purpose. Every /v1 route is metered, so every one needs a principal; there is no
 * anonymous door and the note on `V1_ROUTES` explains why that is permanent, not incidental. The
 * union previously carried a `"public"` member no route used, which bought a dead branch in the
 * OpenAPI builder and a test guard that could never fail. Adding an anonymous route means widening
 * this type deliberately — and revisiting that note first.
 */
export type V1Security = "apiKey";

/**
 * An object schema whose `shape` is statically known to hold zod schemas. The bare `z.ZodObject`
 * types `shape` as `any`, which loses every property type the moment the OpenAPI generator walks
 * it to build parameter entries.
 */
export type V1ObjectSchema = z.ZodObject<Record<string, z.ZodType>>;

export interface V1RouteRequest {
  /** Path parameters, e.g. `{id}`. */
  readonly params?: V1ObjectSchema;
  /** Query-string parameters. Values are coerced from strings. */
  readonly query?: V1ObjectSchema;
  /** JSON request body. */
  readonly body?: V1ObjectSchema;
}

export interface V1Route {
  /** Stable identifier — becomes the OpenAPI operationId and the SDK method name. */
  readonly operationId: string;
  /** Path template with `{param}` placeholders, including the `/v1` prefix. */
  readonly path: string;
  readonly method: V1HttpMethod;
  readonly summary: string;
  readonly tags: readonly string[];
  readonly security: V1Security;
  readonly request: V1RouteRequest;
  /** Status code → response body schema. Every route has exactly one 2xx entry. */
  readonly responses: Readonly<Record<number, z.ZodType>>;
}

/**
 * Builds the error half of a `responses` map. Every non-2xx response on this API carries the
 * same envelope, so listing the statuses is the whole declaration.
 */
function errorResponses(
  ...statuses: readonly V1ErrorStatus[]
): Readonly<Record<number, z.ZodType>> {
  return Object.fromEntries(statuses.map((status) => [status, V1ErrorSchema]));
}

/**
 * THE v1 API contract, as data.
 *
 * This table is the single source of truth for the surface: `scripts/generate-openapi.ts`
 * renders it into apps/docs/openapi/openapi.json, and the route handlers are expected to
 * implement exactly these paths, methods, and status codes. Adding an endpoint means adding a
 * row here first.
 *
 * Every route requires a credential, including the read-only search and category endpoints: this
 * is a metered developer API, and per-key rate limiting and usage accounting need a principal on
 * every request. (The equivalent buyer-facing browse surface is the web app's own market pages,
 * which remain public and do not go through /v1.)
 *
 * The PRIMARY credential is the `x-api-key` header, which is what every generated client and the
 * SDK send and what the security scheme below declares. The handlers additionally accept a
 * signed-in browser cookie session, so a seller can explore their own API from a logged-in tab
 * without minting a key first; key-authenticated WRITES carry the extra `api_write` entitlement
 * requirement that cookie traffic (the sell UI's own) does not. The cookie path is deliberately
 * not modelled per-route here: it is an interactive convenience, not part of the contract a
 * client programs against.
 */
